/*
 * A006843  Triangle read by rows: row n gives denominators of Farey series of
 *          order n.
 * https://oeis.org/A006843
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, nice, frac, tabf
 * Formula:   row r lists denominators of the Farey series F_r, generated by
 *            the next-term rule (a/b, c/d) -> (c/d, (k*c-a)/(k*d-b)) with k =
 *            floor((r+b)/d); row r has 1 + Sum_{k=1..r} phi(k) terms
 * Range:     u8 n <= 9615, u16 n <= 9615, u32 n <= 9615, u64 n <= 9615,
 *            u128 n <= 9615, big any n
 * Helpers:   a6843_phi
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/a6843_phi.h"

seq_t a(idx_t n) {
    unsigned long long row = 1;
    unsigned long long idx_start = 1;
    unsigned long long row_len = 2; /* 1 + phi(1) */

    while (idx_start + row_len <= (unsigned long long)n) {
        idx_start += row_len;
        row++;
        row_len += a6843_phi(row);
    }

    unsigned long long pos = (unsigned long long)n - idx_start;
    unsigned long long N = row;
    unsigned long long pa = 0, pb = 1, pc = 1, pd = N;
    unsigned long long i;

    if (pos == 0) return (seq_t)pb;
    for (i = 1; i < pos; i++) {
        unsigned long long k = (N + pb) / pd;
        unsigned long long e = k * pc - pa;
        unsigned long long f = k * pd - pb;
        pa = pc; pb = pd;
        pc = e; pd = f;
    }
    return (seq_t)pd;
}
